/PROG PICK_PLACE_A
/ATTR
OWNER = MNEDITOR;
COMMENT = "auto";
/MN
   1:  UFRAME_NUM=1 ;
   2:  UTOOL_NUM=1 ;
   3:  !Pick from conveyor and place on Fixture A ;
   4:  !Approach above pick and place, slow contact moves for pick/place ;
   5:  !Wait after gripper actions for part settle ;
   6:  !pick from conveyor ;
   7:  J PR[1:home] 100% FINE ;
   8:  L PR[6:conveyor approach] 100mm/sec CNT50 ;
   9:  L PR[5:conveyor pick] 50mm/sec FINE ;
  10:  RO[1:gripper close]=ON ;
  11:  WAIT 1.00(sec) ;
  12:  IF RI[1]=OFF,JMP LBL[20] ;
  13:  L PR[6:conveyor approach] 100mm/sec CNT50 ;
  14:  L PR[7:fixture A approach] 100mm/sec CNT50 ;
  15:  L PR[8:fixture A place] 50mm/sec FINE ;
  16:  RO[2:gripper open]=ON ;
  17:  WAIT 1.00(sec) ;
  18:  J PR[1:home] 100% FINE ;
  19:  JMP LBL[99] ;
  20:  !Gripper feedback not detected, open gripper and abort to home ;
  21:  RO[2:gripper open]=ON ;
  22:  WAIT 1.00(sec) ;
  23:  J PR[1:home] 100% FINE ;
  24:  LBL[99] ;
/POS
/END

